81	/// A candidate whose current first manifest path exists at `rev` owns it. When none does, the package moved or changed
82	/// its primary manifest, so ownership is whichever package has a manifest named `name` today in an ecosystem where
83	/// `rev` also held a manifest named `name`.
84	pub(crate) fn sole_owner_at<'p>(
85	    git: &GitAccess<'_>,
86	    rev: &str,
87	    name: &str,
88	    candidates: &[&'p Package],
89	    identity: &IdentityIndex,
90	    rosters: &mut Rosters,
91	) -> Result<Option<&'p Package>, GraphError> {
92	    let mut owner = None;
93	    for pkg in candidates {
94	        let Some(manifest) = pkg.canonical_manifests().next() else {
95	            continue;
96	        };
97	        if git.path_exists_at(rev, Path::new(&manifest.path))? {
...
93	                return Ok(None);
94	            }
95	            owner = Some(*pkg);
96	        }
97	    }
98	    if owner.is_some() {
99	        return Ok(owner);
100	    }
101	    let declaring = rosters.declaring_at(git, rev, name)?;
102	    let mut holders = candidates.iter().filter(|pkg| {
103	        declaring.iter().any(|ecosystem| {
104	            identity
105	                .native_name(&pkg.id, *ecosystem)
106	                .is_some_and(|native| names_equal(*ecosystem, native, name))
107	        })
108	    });
109	    let first = holders.next();
110	    Ok(if holders.next().is_some() { None } else { first.copied() })
