        operations,
        prepared,
        index: OpIndex {
            forge_by_package,
            uploads_by_package,
            ..
        },
    } = ops;

    let mut artifact_slots = Vec::new();
    if let (Some(product), Some(policy)) = (&workspace.config.product_release, artifact_policy) {
