/// The build pins `SOURCE_DATE_EPOCH` to this output, so it must be whole seconds.
#[test]
fn git_show_prints_the_committer_time() {
    if !tool_available("git") {
        return;
    }
    let repo = tempfile::tempdir().unwrap();
    let git_in = |args: &[&str]| {
        let output = Command::new("git")
            .args(args)
            .current_dir(repo.path())
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .env("GIT_COMMITTER_DATE", "1700000000 +0000")
            .env("GIT_AUTHOR_DATE", "1700000000 +0000")
            .output()
            .unwrap();
        String::from_utf8_lossy(&output.stdout).trim().to_owned()
    };
    git_in(&["init", "-q"]);
    git_in(&[
        "-c",
        "user.name=t",
        "-c",
        "user.email=t@example.com",
        "-c",
        "commit.gpgsign=false",
        "commit",
        "--allow-empty",
        "-qm",
        "x",
    ]);
    let shape = tool_shape("git", &["show"]).expect("show shape");
    assert_eq!(shape.flags, ["-s", "--format"]);
    assert_eq!(git_in(&["show", "-s", "--format=%ct", "HEAD"]), "1700000000");
}

