            "non-broken admitted member must still be discovered, got: {projects:?}"
        );
        assert!(
            !projects.iter().any(|p| p.path == Path::new("scratch")),
            "the unparseable, non-admitted manifest must not appear as a discovered project, got: {projects:?}"
        );
    }
