    }
    std::fs::create_dir(changesets.join("nested.md")).unwrap();

    let names: Vec<_> = list_changeset_files(&changesets)
        .unwrap()
        .iter()
        .map(|path| path.file_name().unwrap().to_string_lossy().into_owned())
        .collect();
    assert_eq!(names, ["a.md", "b.md"]);
}

