75	/// Workspace-membership filter shared by Cargo's `[workspace]` and uv's
76	/// `[tool.uv.workspace]` -- both use the identical members/exclude
77	/// glob-array shape, including a root manifest that is itself both a
78	/// package/project and a workspace root (hybrid root). `NpmMembership`
79	/// deliberately does NOT go through this type: npm's shape genuinely
80	/// differs (JSON not TOML, no `exclude` concept, and a pnpm-workspace.yaml
81	/// fallback with its own precedence rules).
82	pub(crate) struct Membership {
83	    members: Option<NegatableGlobSet>,
84	    exclude: NegatableGlobSet,
85	    hybrid_root: bool,
86	}
87	
88	impl Membership {
89	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
90	    /// `is_root` is true exactly when `rel == Path::new(".")`.
91	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
92	        if is_root && self.hybrid_root {
93	            return true;
94	        }
95	        if self.exclude.is_match(rel) {
96	            return false;
97	        }
98	        match &self.members {
99	            None => true,
100	            Some(members) => members.is_match(rel),
101	        }
102	    }
103	
104	    /// Unlike [`Self::admits`], `None` `members` (no `[workspace]` restriction present, or the
105	    /// root manifest itself failed to parse) never counts here -- only a real `members`/
106	    /// `exclude` glob match, or the hybrid-root case, both derived from a manifest that
107	    /// actually parsed.
108	    pub(crate) fn admits_explicitly(&self, rel: &Path, is_root: bool) -> bool {
109	        if is_root && self.hybrid_root {
110	            return true;
111	        }
112	        match &self.members {
113	            Some(members) => !self.exclude.is_match(rel) && members.is_match(rel),
114	            None => false,
115	        }
116	    }
117	
118	    fn absent() -> Self {
119	        Membership {
120	            members: None,
121	            exclude: NegatableGlobSet::empty(),
122	            hybrid_root: false,
123	        }
124	    }
125	}
126	
127	/// Safely parses a TOML array-of-strings item, returning `None` for any
128	/// other shape (bare string, table, non-string entries, etc.) instead of
129	/// panicking.
130	fn parse_toml_string_array(item: &toml_edit::Item) -> Option<Vec<String>> {
131	    let arr = item.as_array()?;
132	    let mut out = Vec::with_capacity(arr.len());
133	    for v in arr.iter() {
134	        out.push(v.as_str()?.to_string());
135	    }
136	    Some(out)
137	}
