139	/// Describes where an ecosystem's workspace-membership table lives inside
140	/// its root manifest, so [`read_membership`] can walk to it generically
141	/// instead of each ecosystem hand-rolling the same members/exclude/
142	/// hybrid-root logic around a different table path.
143	pub(crate) struct MembershipSpec {
144	    /// The root manifest's file name, e.g. `Cargo.toml`.
145	    manifest_file_name: &'static str,
146	    /// Nested table keys leading to the workspace table, walked in order
147	    /// from the document root, e.g. `["workspace"]` for Cargo or
148	    /// `["tool", "uv", "workspace"]` for uv-based Python.
149	    table_path: &'static [&'static str],
150	    /// Top-level key whose co-presence with the workspace table marks a
151	    /// hybrid root, e.g. `"package"` for Cargo or `"project"` for Python.
152	    owner_key: &'static str,
153	}
154	
155	pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
156	    manifest_file_name: ManifestFormat::CargoToml.file_name(),
157	    table_path: &["workspace"],
158	    owner_key: "package",
159	};
160	
161	pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
162	    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
163	    table_path: &["tool", "uv", "workspace"],
164	    owner_key: "project",
165	};
166	
167	/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
168	/// (2) a well-formed workspace table with members/exclude arrays of
169	/// strings. Every other shape (workspace table absent, TOML unparseable,
170	/// members/exclude present but not an array-of-strings, members key
171	/// absent) falls back to an absent-filter (admit-all) result -- see the
172	/// `cargo_membership_tests`/`python_membership_tests` modules for the
173	/// exact fallback matrix this is pinned against.
174	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
175	    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
176	        Ok(c) => c,
177	        Err(_) => return Membership::absent(),
178	    };
179	    let doc = match content.parse::<toml_edit::DocumentMut>() {
180	        Ok(d) => d,
181	        Err(_) => return Membership::absent(),
182	    };
183	
184	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
185	    for key in &spec.table_path[1..] {
186	        cursor = cursor.and_then(|c| c.get(*key));
187	    }
188	
189	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
190	    let Some(workspace) = cursor else {
191	        return Membership {
192	            members: None,
193	            exclude: NegatableGlobSet::empty(),
194	            hybrid_root,
195	        };
196	    };
197	    let members = workspace
198	        .get("members")
199	        .and_then(parse_toml_string_array)
200	        .map(|v| build_globset(&v));
201	    let exclude = workspace
202	        .get("exclude")
203	        .and_then(parse_toml_string_array)
204	        .map(|v| build_globset(&v))
205	        .unwrap_or_else(NegatableGlobSet::empty);
206	    Membership {
207	        members,
208	        exclude,
209	        hybrid_root,
210	    }
211	}
212	
213	pub(crate) fn read_cargo_membership(root: &Path) -> Membership {
214	    read_membership(root, &CARGO_MEMBERSHIP_SPEC)
215	}
216	
217	pub(crate) fn read_python_membership(root: &Path) -> Membership {
218	    read_membership(root, &PYTHON_MEMBERSHIP_SPEC)
219	}
