fn parse_error(path: &Path, message: String) -> LocateError {
    LocateError::ManifestParseError {
        path: path.to_path_buf(),
        message,
    }
}

fn invalid_membership(path: &Path, message: String) -> LocateError {
    LocateError::InvalidMembership {
        path: path.to_path_buf(),
        message,
    }
