def remove_fn(path, name):
    s = open(root + path).read()
    m = re.search(r'^( *)fn ' + re.escape(name) + r'\(\)', s, re.M)
    assert m, name
    indent = m.group(1)
    start = m.start()
    before = s[:start].split('\n')[:-1]
    j = len(before)
    while j > 0 and before[j - 1].lstrip().startswith(('///', '#[test]', '//')):
        j -= 1
    start = len('\n'.join(before[:j])) + (1 if j > 0 else 0)
    end = s.index('\n' + indent + '}\n', m.end()) + len('\n' + indent + '}\n')
