128	/// Writes `plan` to disk and stages the touched paths in git.
129	///
130	/// Every side effect here is unconditional -- whether to apply at all is
131	/// the caller's decision, which is why an [`ApplyPermit`] is required
132	/// rather than a `dry_run` bool: a bool carries no guarantee any caller
133	/// actually consulted it. A dry-run caller can't obtain a permit and
134	/// simply doesn't call this function; it reports `plan` instead.
135	///
136	/// # Errors
137	///
138	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
139	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
140	/// - I/O errors writing changelog sections or `pre.json`.
141	pub fn apply_version_plan<R: CommandRunner>(
142	    root: &Path,
143	    plan: &VersionPlan,
